 "content": "def transform(grid):
    """Project marker rays between matching colored boundary segments."""
    h, w = len(grid), len(grid[0])
    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    def oriented(src):
        H, W = len(src), len(src[0])
        out = [row[:] for row in src]

        def runs_on_edge(col):
            runs = []
            r = 0
            while r < H:
                if src[r][col] == background:
                    r += 1
                    continue
                color, start = src[r][col], r
                while r + 1 < H and src[r + 1][col] == color:
                    r += 1
                runs.append((start, r, color))
                r += 1
            return runs

        left, right = runs_on_edge(0), runs_on_edge(W - 1)
        # Pair left/right boundary segments by their order. A marker within a
        # segment casts a ray toward that segment's edge and projects its
        # offset onto the corresponding segment at the opposite edge.
        for r in range(H):
            for c in range(1, W - 1):
                color = src[r][c]
                if color == background:
                    continue
                source_side = None
                source_idx = None
                source_run = None
                for side, runs in ((0, left), (W - 1, right)):
                    for idx, run in enumerate(runs):
                        if run[0] <= r <= run[1]:
                            source_side, source_idx, source_run = side, idx, run
                            break
                    if source_run is not None:
                        break
                if source_run is None:
                    continue
                other_runs = right if source_side == 0 else left
                if source_idx >= len(other_runs):
                    continue
                start, end, _ = source_run
                other_start, other_end, _ = other_runs[source_idx]
                target_r = other_start + (r - start)
                if target_r > other_end:
                    continue

                # Fill between the source edge and marker, then mark its tip.
                if source_side == 0:
                    ray = range(1, c)
                else:
                    ray = range(c + 1, W - 1)
                for x in ray:
                    if out[r][x] == background:
                        out[r][x] = color
                out[r][c] = 4

                # A projected stripe fills background cells only, preserving
                # boundary bars and any pre-existing colored markers.
                for x in range(W):
                    if out[target_r][x] == background:
                        out[target_r][x] = color
        return out

    # The same rule applies when the boundary segments are horizontal; rotate
    # the grid by transposing, apply the vertical version, then transpose back.
    left_count = sum(grid[r][0] != background for r in range(h))
    right_count = sum(grid[r][-1] != background for r in range(h))
    if left_count and right_count:
        return oriented(grid)
    transposed = [list(row) for row in zip(*grid)]
    transposed_result = oriented(transposed)
    return [list(row) for row in zip(*transposed_result)]

