def transform(grid):
    """Project a marker's color back to its nearby edge and across to its pair."""
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Normalize so that the two long boundary bars are on the left and right.
    if any(grid[r][0] != background for r in range(h)) and any(
        grid[r][w - 1] != background for r in range(h)
    ):
        return _vertical(grid, background)

    transposed = [list(row) for row in zip(*grid)]
    result = _vertical(transposed, background)
    return [list(row) for row in zip(*result)]


def _runs(values, background):
    result = []
    i = 0
    while i < len(values):
        if values[i] == background:
            i += 1
            continue
        color, start = values[i], i
        while i + 1 < len(values) and values[i + 1] == color:
            i += 1
        result.append((start, i, color))
        i += 1
    return result


def _vertical(grid, background):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    left_runs = _runs([grid[r][0] for r in range(h)], background)
    right_runs = _runs([grid[r][w - 1] for r in range(h)], background)

    for r in range(h):
        for c in range(1, w - 1):
            color = grid[r][c]
            if color == background:
                continue

            match = None
            for side, edge_runs in ((0, left_runs), (1, right_runs)):
                for index, run in enumerate(edge_runs):
                    if run[0] <= r <= run[1]:
                        match = (side, index, run)
                        break
                if match is not None:
                    break
            if match is None:
                continue

            side, index, source_run = match
            opposite_runs = right_runs if side == 0 else left_runs
            if index >= len(opposite_runs):
                continue
            start, end, _ = source_run
            opposite_start, opposite_end, _ = opposite_runs[index]
            projected_row = opposite_start + (r - start)
            if projected_row > opposite_end:
                continue

            # Color the row segment between the source edge and marker.
            if side == 0:
                ray = range(1, c)
                opposite_edge_col = w - 1
            else:
                ray = range(c + 1, w - 1)
                opposite_edge_col = 0
            for x in ray:
                out[r][x] = color
            out[r][c] = 4

            # Project the relative position across the opposite edge segment.
            # Preserve the colored edge cell and fill the rest of the row.
            for x in range(w):
                if x != opposite_edge_col:
                    out[projected_row][x] = color

