def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Select the pair of opposing edges that carries the frame segments.
    vertical = (any(grid[r][0] != background for r in range(h)) and
                any(grid[r][-1] != background for r in range(h)))
    if vertical:
        edge_a = [grid[r][0] for r in range(h)]
        edge_b = [grid[r][-1] for r in range(h)]
        runs_a = _runs(edge_a, background)
        runs_b = _runs(edge_b, background)
        _apply(grid, out, background, runs_a, runs_b, vertical=True)
    else:
        edge_a = grid[0]
        edge_b = grid[-1]
        runs_a = _runs(edge_a, background)
        runs_b = _runs(edge_b, background)
        _apply(grid, out, background, runs_a, runs_b, vertical=False)
    return out


def _runs(values, background):
    result = []
    i = 0
    while i < len(values):
        if values[i] == background:
            i += 1
            continue
        color, start = values[i], i
        while i + 1 < len(values) and values[i + 1] == color:
            i += 1
        result.append((start, i, color))
        i += 1
    return result


def _apply(grid, out, background, runs_a, runs_b, vertical):
    h, w = len(grid), len(grid[0])
    markers = []
    if vertical:
        for r in range(h):
            for c in range(1, w - 1):
                if grid[r][c] != background:
                    markers.append((r, c, grid[r][c]))
    else:
        for r in range(1, h - 1):
            for c in range(w):
                if grid[r][c] != background:
                    markers.append((r, c, grid[r][c]))

    # Count markers per source boundary segment to determine if the projected
    # line ends just inside an opposing frame containing multiple rays.
    grouped = {}
    for r, c, color in markers:
        pos = r if vertical else c
        found = None
        for side, runs in ((0, runs_a), (1, runs_b)):
            for idx, run in enumerate(runs):
                if run[0] <= pos <= run[1]:
                    found = side, idx, run
                    break
            if found is not None:
                break
        if found is None:
            continue
        side, idx, run = found
        grouped.setdefault((side, idx), []).append((r, c, color, run))

    for (side, idx), group in grouped.items():
        opposite = runs_b if side == 0 else runs_a
        if idx >= len(opposite):
            continue
        source_run = runs_a[idx] if side == 0 else runs_b[idx]
        other_run = opposite[idx]
        source_start, source_end, _ = source_run
        other_start, other_end, _ = other_run
        for r, c, color, _ in group:
            pos = r if vertical else c
            target_pos = other_start + (pos - source_start)
            if target_pos > other_end:
                continue

