                # Ray from its source edge to the marker; marker becomes 4.
                xs = range(1, c) if side == 0 else range(c + 1, w - 1)
                for x in xs:
                    out[r][x] = color
                out[r][c] = 4
                # Project the marker's within-segment offset across the row.
                for x in range(w):
                    if out[target_pos][x] == background:
                        out[target_pos][x] = color
            else:
                # Horizontal counterpart: ray from top/bottom edge to marker.
                ys = range(1, r) if side == 0 else range(r + 1, h - 1)
                for y in ys:
                    out[y][c] = color
                out[r][c] = 4
                # A lone projected ray may reach the far grid edge; multiple
