                if side == 0:
                    y_range = range(1, h - 1) if len(group) > 1 else range(1, h)
                else:
                    y_range = range(0, h - 1) if len(group) > 1 else range(h - 1, -1, -1)
                for y in y_range:
                    if out[y][target_pos] == background:
                        out[y][target_pos] = color
