    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Normalize so active boundary bars lie on left/right edges.
    if any(grid[r][0] != background for r in range(h)) and any(
        grid[r][-1] != background for r in range(h)
    ):
        return _solve_vertical(grid, background)
