def _solve_vertical(grid, background):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    left = _runs([grid[r][0] for r in range(h)], background)
    right = _runs([grid[r][w - 1] for r in range(h)], background)

    for r in range(h):
        for c in range(1, w - 1):
            marker = grid[r][c]
            if marker == background:
                continue

            # Locate the boundary segment containing the marker's row.
            match = None
            for side, runs in ((0, left), (1, right)):
                for index, run in enumerate(runs):
                    if run[0] <= r <= run[1]:
                        match = side, index, run
                        break
                if match is not None:
                    break
            if match is None:
                continue
            side, index, (start, end, _) = match
            opposite = right if side == 0 else left
            if index >= len(opposite):
                continue
            other_start, other_end, _ = opposite[index]
            projected_row = other_start + (r - start)
            if projected_row > other_end:
                continue

            # Draw the marker's ray back to the edge it belongs to; tip becomes 4.
            if side == 0:
                for x in range(1, c):
                    out[r][x] = marker
            else:
                for x in range(c + 1, w - 1):
                    out[r][x] = marker
            out[r][c] = 4

            # Project the marker offset onto the paired segment. Preserve that
            # edge's own color; fill the whole row up to but not including it.
            if side == 0:
                for x in range(w - 1):
                    out[projected_row][x] = marker
            else:
                for x in range(1, w):
                    out[projected_row][x] = marker
    return out


